#!/usr/bin/env python3
"""Remove JavaScript from HTML files to prevent XSS attacks.

Usage: filter.py <html_file>

Modifies the file in-place. Preserves all legitimate HTML structure and
content; only removes JavaScript and other script-capable vectors.
"""
import sys
import re
import html as html_module
from bs4 import BeautifulSoup, Comment

# Attributes whose values are URLs and can carry javascript: or data: schemes
_URL_ATTRS = {
    'href', 'src', 'action', 'formaction', 'background',
    'codebase', 'data', 'dynsrc', 'lowsrc', 'usemap',
    'longdesc', 'profile', 'cite', 'poster', 'xlink:href',
}

_JS_RE = re.compile(r'^\s*javascript\s*:', re.IGNORECASE)


def _clean_url(value):
    """Normalize a URL value for scheme detection.

    Handles HTML entity encoding, leading/trailing whitespace, and the
    control characters that browsers ignore during URL parsing.
    """
    if value is None:
        return ''
    if isinstance(value, list):
        value = ' '.join(str(v) for v in value)
    # Decode HTML entities (e.g. &colon; or &#58;)
    decoded = html_module.unescape(str(value))
    # Strip all ASCII control characters (browsers ignore them in URLs)
    cleaned = re.sub(r'[\x00-\x20\x7f]', '', decoded)
    return cleaned


def _is_dangerous_url(value):
    """Return True if the URL value is a javascript: or dangerous data: URL."""
    cleaned = _clean_url(value)
    if _JS_RE.match(cleaned):
        return True
    if re.match(r'^data\s*:\s*text/html', cleaned, re.IGNORECASE):
        return True
    if re.match(r'^data:', cleaned, re.IGNORECASE):
        if re.search(r'<\s*script', cleaned, re.IGNORECASE):
            return True
    return False


def _is_dangerous_meta_refresh(content_value, http_equiv):
    """Check whether a <meta> refresh redirects to a dangerous URL."""
    if not http_equiv or 'refresh' not in http_equiv.lower():
        return False
    if not content_value:
        return False
    # Extract the url= portion of the refresh directive
    match = re.search(r'url\s*=\s*(.*)', str(content_value), re.IGNORECASE)
    if not match:
        return False
    url = match.group(1).strip().strip("'\"")
    return _is_dangerous_url(url)


def _filter_soup(soup):
    """Remove all JavaScript vectors from a parsed BeautifulSoup tree."""

    # 1. Remove every <script> element (HTML, SVG, MathML, …)
    for script in soup.find_all('script'):
        script.decompose()

    # 2. Remove HTML comments (conditional comments can hide IE-only JS)
    for comment in soup.find_all(string=lambda t: isinstance(t, Comment)):
        comment.extract()

    # 3. Walk every element and strip dangerous attributes
    for tag in soup.find_all(True):
        if not tag.attrs:
            continue
        tag_name = (tag.name or '').lower()
        attrs_to_delete = []

        for attr_name, attr_value in list(tag.attrs.items()):
            lower = attr_name.lower()

            # 3a. Any on* attribute is an event handler
            if lower.startswith('on'):
                attrs_to_delete.append(attr_name)
                continue

            # 3b. URL-bearing attributes
            if lower in _URL_ATTRS:
                if _is_dangerous_url(attr_value):
                    attrs_to_delete.append(attr_name)
                continue

            # 3c. iframe srcdoc
            if lower == 'srcdoc':
                if re.search(r'<\s*script', str(attr_value), re.IGNORECASE):
                    attrs_to_delete.append(attr_name)
                continue

            # 3d. <meta> refresh with dangerous URL
            if lower == 'content' and tag_name == 'meta':
                http_equiv = tag.get('http-equiv', '')
                if _is_dangerous_meta_refresh(attr_value, http_equiv):
                    attrs_to_delete.append(attr_name)
                continue

        for attr_name in attrs_to_delete:
            del tag[attr_name]


def filter_html(html_string):
    """Return the HTML string with all JavaScript removed."""
    soup = BeautifulSoup(html_string, 'html.parser')
    _filter_soup(soup)
    return str(soup)


def main():
    if len(sys.argv) < 2:
        print('Usage: filter.py <html_file>', file=sys.stderr)
        sys.exit(1)

    path = sys.argv[1]
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        original = f.read()

    filtered = filter_html(original)

    with open(path, 'w', encoding='utf-8') as f:
        f.write(filtered)


if __name__ == '__main__':
    main()
